49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Pragmatic check for a syntactically valid email address: a non-empty local
62	     * part, a single '@', and a domain with at least one dot-separated label.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
66	
67	    /**
68	     * Common street-type abbreviations expanded during address normalization,
69	     * keyed by their upper-cased form.
70	     */
71	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
72	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper) {
86	        this.clinicService = clinicService;
87	        this.ownerMapper = ownerMapper;
88	        this.petMapper = petMapper;
89	        this.visitMapper = visitMapper;
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
95	        Collection<Owner> owners;
96	        if (lastName != null) {
97	            owners = this.clinicService.findOwnerByLastName(lastName);
98	        } else {
99	            owners = this.clinicService.findAllOwners();
100	        }
101	        if (owners.isEmpty()) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
110	        Owner owner = this.clinicService.findOwnerById(ownerId);
111	        if (owner == null) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        // Validate & normalize the optional email; reject the create when it is present but invalid.
121	        if (!normalizeEmail(ownerFieldsDto)) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
125	        // abbreviations) and store the normalized form back on the DTO so it is what gets
126	        // persisted and compared. Reject the create when the address is blank once normalized.
127	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
128	        if (canonicalAddress.isBlank()) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        ownerFieldsDto.setAddress(canonicalAddress);
132	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
133	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
134	        if (normalizedTelephone == null) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        // Reject the create if any existing owner already uses this telephone (compared in E.164 form).
138	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
139	            .map(Owner::getTelephone)
140	            .map(OwnerRestControllerV1::toE164)
141	            .filter(existing -> existing != null)
142	            .anyMatch(normalizedTelephone::equals);
143	        if (telephoneInUse) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        // Reject the create when another owner already shares this owner's last name and address
147	        // (compared case-insensitively with collapsed whitespace), unless the request opts into
148	        // sharing a household.
149	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
150	            String normalizedLastName = normalizeHouseholdKey(ownerFieldsDto.getLastName());
151	            String normalizedAddress = normalizeHouseholdKey(ownerFieldsDto.getAddress());
152	            boolean householdInUse = this.clinicService.findAllOwners().stream()
153	                .anyMatch(existing ->
154	                    normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
155	                        && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress));
156	            if (householdInUse) {
157	                return new ResponseEntity<>(HttpStatus.CONFLICT);
158	            }
159	        }
160	        ownerFieldsDto.setTelephone(normalizedTelephone);
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        // Default the registration date to the server's current date when none was supplied.
164	        if (owner.getRegistrationDate() == null) {
165	            owner.setRegistrationDate(LocalDate.now());
166	        }
167	        // Assign the customer code as '<LAST3>-<NNNN>': the upper-cased first three letters
168	        // of the last name, and a global 4-digit sequence one greater than the current owner count.
169	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
170	        this.clinicService.saveOwner(owner);
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Validate and normalize the optional owner email in place.
179	     *
180	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
181	     * When present it must be a syntactically valid address; a valid address is
182	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
183	     * present but syntactically invalid, so the caller can reject with 400.
184	     */
185	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
186	        String email = ownerFieldsDto.getEmail();
187	        if (email == null || email.isBlank()) {
188	            ownerFieldsDto.setEmail(null);
189	            return true;
190	        }
191	        String normalized = email.trim().toLowerCase(Locale.ROOT);
192	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
193	            return false;
194	        }
195	        ownerFieldsDto.setEmail(normalized);
196	        return true;
197	    }
198	
199	    /**
200	     * Normalize an owner address: trim, collapse each run of whitespace to a single
201	     * space, upper-case, and expand common street-type abbreviations
202	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
203	     * A {@code null} value normalizes to the empty string.
204	     */
205	    private static String normalizeAddress(String value) {
206	        if (value == null) {
207	            return "";
208	        }
209	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
210	        if (collapsed.isEmpty()) {
211	            return "";
212	        }
213	        String[] tokens = collapsed.split(" ");
214	        StringBuilder sb = new StringBuilder(collapsed.length());
215	        for (int i = 0; i < tokens.length; i++) {
216	            if (i > 0) {
217	                sb.append(' ');
218	            }
219	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
220	        }
221	        return sb.toString();
222	    }
223	
224	    /**
225	     * Normalize an owner household field (last name or address) for duplicate detection:
226	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
227	     * A {@code null} value normalizes to the empty string.
228	     */
229	    private static String normalizeHouseholdKey(String value) {
230	        if (value == null) {
231	            return "";
232	        }
233	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
234	    }
235	
236	    /**
237	     * Normalize a telephone number to E.164 form.
238	     *
239	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
240	     * explicit leading {@code '+'} and country code it is kept; otherwise the
241	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
242	     * dropped from the national digits. The result must contain 8 to 15 digits
243	     * after the {@code '+'}.
244	     *
245	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
246	     *         the input is absent or cannot form a valid E.164 number.
247	     */
248	    private static String toE164(String raw) {
249	        if (raw == null) {
250	            return null;
251	        }
252	        String trimmed = raw.trim();
253	        boolean hasCountryCode = trimmed.startsWith("+");
254	        // Strip spaces, dashes and brackets.
255	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
256	        String digits;
257	        if (hasCountryCode) {
258	            // Keep the explicit country code; drop the leading '+' for validation.
259	            digits = stripped.substring(1);
260	        } else {
261	            // No country code: assume '+61' and drop a single leading '0'.
262	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
263	            digits = "61" + national;
264	        }
265	        if (!digits.matches("\\d{8,15}")) {
266	            return null;
267	        }
268	        return "+" + digits;
269	    }
270	
271	    /**
272	     * Build the next customer code, formatted {@code '<LAST3>-<NNNN>'}.
273	     *
274	     * <p>{@code LAST3} is the upper-cased first three letters of {@code lastName}
275	     * (fewer if the name is shorter), and {@code NNNN} is a global 4-digit
276	     * zero-padded sequence equal to one more than the current number of owners
277	     * (e.g. {@code 'SMI-0007'}).
278	     */
279	    private String nextCustomerCode(String lastName) {
280	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
281	        int sequence = this.clinicService.findAllOwners().size() + 1;
282	        return String.format("%s-%04d", last3, sequence);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
288	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
289	        if (currentOwner == null) {
290	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
291	        }
292	        if (!normalizeEmail(ownerFieldsDto)) {
293	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
294	        }
295	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
296	        if (normalizedTelephone == null) {
297	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
298	        }
299	        currentOwner.setAddress(ownerFieldsDto.getAddress());
300	        currentOwner.setCity(ownerFieldsDto.getCity());
301	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
302	        currentOwner.setLastName(ownerFieldsDto.getLastName());
303	        currentOwner.setTelephone(normalizedTelephone);
304	        currentOwner.setEmail(ownerFieldsDto.getEmail());
305	        this.clinicService.saveOwner(currentOwner);
306	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
307	    }
308	
309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Transactional
311	    @Override
312	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
313	        Owner owner = this.clinicService.findOwnerById(ownerId);
314	        if (owner == null) {
315	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	        }
317	        this.clinicService.deleteOwner(owner);
318	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
324	        Owner owner = this.clinicService.findOwnerById(ownerId);
325	        if (owner == null) {
326	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	        }
328	        HttpHeaders headers = new HttpHeaders();
329	        Pet pet = petMapper.toPet(petFieldsDto);
330	        owner.setId(ownerId);
331	        pet.setOwner(owner);
332	        pet.getType().setName(null);
333	        this.clinicService.savePet(pet);
334	        PetDto petDto = petMapper.toPetDto(pet);
335	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
336	            .buildAndExpand(pet.getId()).toUri());
337	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
338	    }
339	
340	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
341	    @Override
342	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
343	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
344	        if (currentOwner != null) {
345	            Pet currentPet = this.clinicService.findPetById(petId);
346	            if (currentPet != null) {
347	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
348	                currentPet.setName(petFieldsDto.getName());
349	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
350	                this.clinicService.savePet(currentPet);
351	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
352	            }
353	        }
354	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
360	        HttpHeaders headers = new HttpHeaders();
361	        Visit visit = visitMapper.toVisit(visitFieldsDto);
362	        Pet pet = new Pet();
363	        pet.setId(petId);
364	        visit.setPet(pet);
365	        this.clinicService.saveVisit(visit);
366	        VisitDto visitDto = visitMapper.toVisitDto(visit);
367	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
368	            .buildAndExpand(visit.getId()).toUri());
369	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
370	    }
371	
372	
373	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
374	    @Override
375	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
376	        Owner owner = this.clinicService.findOwnerById(ownerId);
377	        if (owner != null) {
378	            Pet pet = owner.getPet(petId);
379	            if (pet != null) {
380	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
381	            }
382	        }
383	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
384	    }
385	}
